struct noArvore {
   int dado;
   noArvore *esquerda;
   noArvore *direita;
};
noArvore *insere(noArvore *arvore, int valor) {
   if (arvore == NULL) {
      arvore = new noArvore;
      arvore->esquerda = NULL;
      arvore->direita = NULL;
      arvore->dado = valor;
   } else if(valor < arvore->dado) {
        arvore->esquerda = insere (arvore->esquerda, valor);
     }
     else {
        arvore->direita = insere (arvore->direita, valor);
     }
     return(arvore);
}
